using System.Collections.Generic;

namespace RainbowSense.VisualStudio.Completion.Catalogs;

public sealed class DevExpressComponent
{
    public DevExpressComponent(string tagName, string namespaceName, string category, string typeName, string arity, string documentation)
    {
        TagName = tagName;
        NamespaceName = namespaceName;
        Category = category;
        TypeName = typeName;
        Arity = arity;
        Documentation = documentation;
    }

    public string TagName { get; }

    public string NamespaceName { get; }

    public string Category { get; }

    public string TypeName { get; }

    public string Arity { get; }

    public string Documentation { get; }

    public string DisplayName => Arity.Length > 0 ? TypeName + "<" + Arity + ">" : TypeName;

    public string SortPrefix => Category.Length > 0 ? Category.Substring(0, 1) : "9";
}

