    public static IReadOnlyList<DevExpressComponent> Items => _items;

    public static DevExpressComponent Find(string tagName)
    {
        foreach (DevExpressComponent item in _items)
        {
            if (string.Equals(item.TagName, tagName, System.StringComparison.Ordinal))
                return item;
        }

        return null;
    }
